original_waitpid = os.waitpid original_kill, original_killpg = os.kill, os.killpg original_signal = worker_capture._signal original_monotonic = time.monotonic cleanup_cutoff = False calls = [] observed = [] end = time.monotonic() + 0.3
def child(control, result, token, argv, deadline): try: inspection.reset_after_fork({control, result}) if ready: message = { "token": token, "pid": os.getpid(), "pgid": os.getpgrp(), "sid": os.getsid(0), } worker_capture._write(control, json.dumps(message).encode() + b"\n", deadline) # No helper is created. TERM/KILL and child lifetime remain real. while True: signal.pause() finally: os._exit(70)
def waitpid(pid, flags): now = time.monotonic() admitted = _admitted("_reap") calls.append( { "operation": "waitpid", "pid": pid, "flags": flags, "time": now, "admitted": admitted, } ) # Simulated deferred observation, not kernel unreapability. The child # can really exit, but its status remains pinned until the independent audit. # Branch on runtime admission, so scheduler delay after it cannot reap early. if (now if admitted is None else admitted) < end or operation != "final-reap": return 0, 0 result = original_waitpid(pid, flags) observed.append(result) return result
def kill(pid, sig): calls.append( { "operation": "kill", "pid": pid, "signal": int(sig), "time": time.monotonic(), "admitted": _admitted("_signal"), } ) return original_kill(pid, sig)
def killpg(pid, sig): calls.append( { "operation": "killpg", "pid": pid, "signal": int(sig), "time": time.monotonic(), "admitted": _admitted("_signal"), } ) return original_killpg(pid, sig)
def monotonic(): return end if cleanup_cutoff else original_monotonic()
def signal_at_cleanup_cutoff(owner, sig): nonlocal cleanup_cutoff if operation == "cleanup-cutoff" and sig == signal.SIGKILL: # capture_helper's cleanup loop has admitted this turn before end. # Cross to equality at its KILL entry; the following reap sees the # same original cutoff. No stale callback is invoked in this case. cleanup_cutoff = True return original_signal(owner, sig)
monkeypatch.setattr(time, "monotonic", monotonic) monkeypatch.setattr(worker_capture, "_signal", signal_at_cleanup_cutoff) monkeypatch.setattr(worker_capture, "_child", child) monkeypatch.setattr(os, "waitpid", waitpid) monkeypatch.setattr(os, "kill", kill) monkeypatch.setattr(os, "killpg", killpg) receipt = worker_capture.capture_helper(("/usr/bin/true",), end) crossed_in_cleanup = cleanup_cutoff cleanup_cutoff = False # The independent audit uses the real clock. worker = receipt.worker pid = worker["pid"] audit = {"pid": pid, "adapter": "deferred parent WNOHANG observation", "reaped": False} try: if operation not in {"final-reap", "cleanup-cutoff"}: owner = worker_capture._owners[pid] with monkeypatch.context() as clock: if operation == "at-cutoff": clock.setattr(time, "monotonic", lambda: end) worker_capture._signal(owner, signal.SIGTERM) worker_capture._signal( owner, signal.SIGTERM if operation == "stale-term" else signal.SIGKILL ) worker_capture._reap(owner) retain(tmp_path, f"worker-deadline-{operation}-{ready}", receipt) assert crossed_in_cleanup is (operation == "cleanup-cutoff") # A syscall may execute after end when the runtime admitted it before end. assert not [call for call in calls if call["admitted"] is None or call["admitted"] >= end] # Admission must be the clock read that leads to this syscall, not a stale one. > assert all(0 <= call["time"] - call["admitted"] < ADMISSION_GAP for call in calls) E assert False E + where False = all(<generator object test_worker_shutdown_deadline_closes_owner_operations.<locals>.<genexpr> at 0x1087b6c00>)
